// src/components/SvgFlow.js
import React from "react";
import ReactFlow, { Background, Controls, MiniMap } from "react-flow-renderer";

const SvgFlow = ({ graph }) => {
  return (
    <div style={{ width: "100%", height: "500px", backgroundColor: "#0d1117", borderRadius: "10px" }}>
      {graph && graph.length > 0 ? (
        <ReactFlow elements={graph}>
          <MiniMap />
          <Controls />
          <Background />
        </ReactFlow>
      ) : (
        <div style={{ color: "#ccc", textAlign: "center", padding: "40px" }}>
          No flowchart yet — click "Generate Flowchart"
        </div>
      )}
    </div>
  );
};

export default SvgFlow;
